import{_ as t,o as e,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Flow: sustainable rhythm","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/flow.md","filePath":"en/guide/combat/flow.md"}'),r={name:"en/guide/combat/flow.md"};function o(d,a,l,s,h,c){return e(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="flow-sustainable-rhythm" tabindex="-1">Flow: sustainable rhythm <a class="header-anchor" href="#flow-sustainable-rhythm" aria-label="Permalink to &quot;Flow: sustainable rhythm&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Experimental rhythm profile · Not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li><a href="/Syrolands-Public/en/guide/glossary.html#flow">Flow</a> rewards a steady <a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Modern</a> rhythm with modest <a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">stamina</a> and <a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">recovery</a> benefits.</li><li>It grants no raw damage or accuracy bonus in the current experiment.</li><li>Pausing clears Flow without punishing inactivity; <a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Legacy</a> uses automatic cadence instead.</li></ul><p><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Meaning</th></tr></thead><tbody><tr><td>Stable</td><td>Ordinary sustainable play without an efficiency bonus.</td></tr><tr><td>Flow</td><td>Consistent available actions build a forgiving rhythm and modest efficiency.</td></tr><tr><td>Off Rhythm</td><td>Rushing or repeated unavailable presses worsen efficiency; steady play restores it.</td></tr><tr><td>Reset</td><td>Pauses, feints, defense, target changes and weapon or mode changes clear the streak.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands</th></tr></thead><tbody><tr><td>Automatic swing cadence</td><td>Modern adds player-controlled rhythm; Legacy keeps automatic cadence.</td></tr><tr><td>Stamina management affects sustained fighting</td><td>Flow adds an explicit efficiency state without turning speed into free damage.</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>You maintain a comfortable rhythm with your sword, then pause to avoid a heavy attack. The pause clears your streak; it is not a punishment for choosing safety.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">Stamina</a> · <a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Modes</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/flow.html">Read the full design specification</a></p><p><span id="flow-rhythm-without-button-mashing"></span></p>',16)])])}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
